// LevelUpdates describes optional bracket price level changes. A nil pointer
// leaves the corresponding level unchanged; a zero target or stoploss removes
// that exit level.
type LevelUpdates struct {
	EntryPrice       *float64
	TargetPrice      *float64
	StopLossPrice    *float64
	ExchangeStopMode *string
}

func validateLevels(transactionType string, entry, target, stop float64) error {
	tt := strings.ToUpper(strings.TrimSpace(transactionType))
	if tt == "BUY" {
		if target > 0 && entry > 0 && target <= entry {
			return errors.New("bracket: target price must be greater than entry price for BUY")
		}
		if stop > 0 && entry > 0 && stop >= entry {
			return errors.New("bracket: stoploss price must be less than entry price for BUY")
		}
		if target > 0 && stop > 0 && target <= stop {
			return errors.New("bracket: target price must be greater than stoploss price for BUY")
		}
	} else if tt == "SELL" {
		if target > 0 && entry > 0 && target >= entry {
			return errors.New("bracket: target price must be less than entry price for SELL")
		}
		if stop > 0 && entry > 0 && stop <= entry {
			return errors.New("bracket: stoploss price must be greater than entry price for SELL")
		}
		if target > 0 && stop > 0 && target >= stop {
			return errors.New("bracket: target price must be less than stoploss price for SELL")
		}
	}
	return nil
}

// UpdateLevels moves or removes a bracket's entry, target or stoploss level.
// Moving a pending entry also modifies the resting broker order in place.
func (e *Engine) UpdateLevels(ctx context.Context, id string, updates LevelUpdates) (*Bracket, error) {
	id = strings.TrimSpace(id)
	if id == "" {
		return nil, errors.New("bracket id is required")
	}

	e.mu.RLock()
	current, ok := e.brackets[id]
	if !ok {
		e.mu.RUnlock()
		return nil, errors.New("bracket not found")
	}
	snapshot := *current
	exec := e.exec
	e.mu.RUnlock()

	if snapshot.Status != StatusPendingEntry && snapshot.Status != StatusInPosition {
		return nil, fmt.Errorf("bracket %s cannot be modified in status %s", id, snapshot.Status)
	}

	entry := snapshot.EntryPrice
	target := snapshot.TargetPrice
	stop := snapshot.StopLossPrice
	exchangeStopMode := snapshot.ExchangeStopMode
	if updates.ExchangeStopMode != nil {
		if snapshot.ExchangeStopIsWorking() || snapshot.ExchangeStopOrderID != "" {
			return nil, errors.New("exchange backstop is live at the broker and cannot be changed from the chart")
		}
		exchangeStopMode = NormalizeExchangeStopMode(*updates.ExchangeStopMode)
		if !validExchangeStopMode(exchangeStopMode) {
			return nil, fmt.Errorf("unsupported exchange stop mode %q", exchangeStopMode)
		}
	}
	if updates.EntryPrice != nil {
		if snapshot.Status != StatusPendingEntry {
			return nil, errors.New("cannot change entry price of an active position")
		}
		if *updates.EntryPrice <= 0 {
			return nil, errors.New("entry price must be positive")
		}
		entry = *updates.EntryPrice
	}
	if updates.TargetPrice != nil {
		if *updates.TargetPrice < 0 {
			return nil, errors.New("target price cannot be negative")
		}
		target = *updates.TargetPrice
	}
	if updates.StopLossPrice != nil {
		if *updates.StopLossPrice < 0 {
			return nil, errors.New("stoploss price cannot be negative")
		}
		stop = *updates.StopLossPrice
	}
	if err := validateLevels(snapshot.TransactionType, entry, target, stop); err != nil {
		return nil, err
	}

	if updates.EntryPrice != nil && snapshot.EntryOrderID != "" {
		if exec == nil {
			return nil, errors.New("order modification is not available")
		}
		order := kotakapi.Order{
			InstrumentKey:   snapshot.InstrumentKey,
			ExchangeSegment: snapshot.ExchangeSegment,
			TradingSymbol:   snapshot.TradingSymbol,
			TransactionType: snapshot.TransactionType,
			Product:         snapshot.Product,
			OrderType:       "L",
			Quantity:        snapshot.Quantity,
			Price:           entry,
			Validity:        "DAY",
		}
		if err := exec.Modify(ctx, snapshot.EntryOrderID, order); err != nil {
			return nil, fmt.Errorf("bracket: modify entry order: %w", err)
		}
	}

	e.mu.Lock()
	current, ok = e.brackets[id]
	if !ok {
		e.mu.Unlock()
		return nil, errors.New("bracket not found")
	}
	if current.Status != StatusPendingEntry && current.Status != StatusInPosition {
		status := current.Status
		e.mu.Unlock()
		return nil, fmt.Errorf("bracket %s cannot be modified in status %s", id, status)
	}
	if updates.EntryPrice != nil && current.Status != StatusPendingEntry {
		e.mu.Unlock()
		return nil, errors.New("bracket entered a position while the entry price was being modified")
	}
	current.EntryPrice = entry
	current.TargetPrice = target
	current.StopLossPrice = stop
	current.ExchangeStopMode = exchangeStopMode
	if updates.StopLossPrice != nil {
		// An explicit stoploss move or removal takes over from trailing logic,
		// otherwise the next tick would immediately re-tighten it.
		current.TrailingStop = 0
	}
	current.UpdatedAt = time.Now()
	updated := *current
	e.mu.Unlock()

	if e.store != nil {
		if err := e.store.UpdateBracket(ctx, updated); err != nil {
			e.log.Error("failed to persist bracket level update", "id", id, "error", err)
		}
	}
	e.notify(updated)
	if updates.ExchangeStopMode != nil && updated.Status == StatusInPosition {
		if mode := NormalizeExchangeStopMode(updated.ExchangeStopMode); mode == "" || mode == ExchangeStopOff {
			return &updated, nil
		}
		e.ensureExchangeStop(ctx, id)
		if refreshed, ok := e.Get(id); ok && refreshed != nil {
			updated = *refreshed
		}
	}
	return &updated, nil
}

// Cancel cancels a pending bracket, cancelling any resting entry order.
func (e *Engine) Cancel(ctx context.Context, id string) error {
	e.mu.Lock()
	b, ok := e.brackets[id]
	if !ok {
		e.mu.Unlock()
		return errors.New("bracket not found")
	}
	if b.Status == StatusInPosition {
		e.mu.Unlock()
		return errors.New("cannot cancel active in-position bracket; use exit to square off")
	}
	if b.Status != StatusPendingEntry {
		currStatus := b.Status
		e.mu.Unlock()
		return fmt.Errorf("bracket %s cannot be cancelled in status %s", id, currStatus)
	}

	orderToCancel := b.EntryOrderID
	exchangeStopOrderID := b.ExchangeStopOrderID
	e.mu.Unlock()

	if exchangeStopOrderID != "" {
		if filled, price, err := e.cancelExchangeStopOrder(ctx, exchangeStopOrderID); filled {
			e.markExchangeStopFill(ctx, id, price)
			return nil
		} else if err != nil {
			e.log.Warn("failed to cancel exchange stop on bracket cancel", "id", id, "order_id", exchangeStopOrderID, "error", err)
		} else {
			e.setExchangeStopStatus(ctx, id, ExchangeStopCancelled)
		}
	}

	if orderToCancel != "" {
		filled, price, err := e.cancelEntryOrder(ctx, orderToCancel)
		if err != nil {
			return fmt.Errorf("bracket: cancel entry order %s: %w", orderToCancel, err)
		}
		if filled {
			e.mu.Lock()
			curr, ok := e.brackets[id]
			if !ok {
				e.mu.Unlock()
				return fmt.Errorf("bracket: entry order %s filled before it could be cancelled", orderToCancel)
			}
			curr.Status = StatusInPosition
			if price > 0 {
				curr.EntryPrice = price
			}
			curr.UpdatedAt = time.Now()
			e.indexActiveInPosition(curr)
			cp := *curr
			e.mu.Unlock()
			e.persistBracket(ctx, cp)
			e.notify(cp)
			e.ensureExchangeStop(ctx, id)
			return fmt.Errorf("bracket: entry order %s filled before it could be cancelled", orderToCancel)
		}
	}

	e.mu.Lock()
	curr, ok := e.brackets[id]
	if !ok {
		e.mu.Unlock()
		return nil
	}
	if curr.Status == StatusCancelled {
		e.mu.Unlock()
		return nil
	}
	if curr.Status != StatusPendingEntry {
		status := curr.Status
		e.mu.Unlock()
		return fmt.Errorf("bracket %s cannot be cancelled in status %s", id, status)
	}
	e.unindexActiveInPosition(curr)
	curr.Status = StatusCancelled
	curr.UpdatedAt = time.Now()
	bracketCopy := *curr
	e.mu.Unlock()

	e.persistBracket(ctx, bracketCopy)
	e.notify(bracketCopy)
	return nil
}

// cancelEntryOrder asks the executor to cancel an entry order and reports
// whether it filled instead. It never mutates bracket state. Confirmation is
// best-effort: an executor that cannot look orders up is trusted to have
// accepted the cancel.
func (e *Engine) cancelEntryOrder(ctx context.Context, orderID string) (bool, float64, error) {
	if e.exec == nil || strings.TrimSpace(orderID) == "" {
		return false, 0, nil
	}
	if err := e.exec.Cancel(ctx, orderID); err != nil {
		return false, 0, err
	}
	for attempt := 0; attempt < 10; attempt++ {
		if attempt > 0 {
			select {
			case <-ctx.Done():
				return false, 0, ctx.Err()
			case <-time.After(100 * time.Millisecond):
			}
		}
		foundID, status, price, err := e.exec.Lookup(ctx, orderID, "")
		if err != nil {
			if errors.Is(err, ErrExecutorUnavailable) || errors.Is(err, ErrOrderNotFound) {
				return false, 0, nil
			}
			return false, 0, err
		}
		if strings.TrimSpace(foundID) == "" {
			return false, 0, nil
		}
		if isFilledStatus(status) {
			return true, price, nil
		}
		if isCancelledStatus(status) {
			return false, 0, nil
		}
		if strings.Contains(strings.ToUpper(status), "PARTIAL") {
			return false, 0, fmt.Errorf("order %s is partially filled", orderID)
		}
	}
	return false, 0, fmt.Errorf("order %s cancel not confirmed", orderID)
}

// exitOrderState reports whether an existing exit order already filled or is
// still working. done is true only when the order is terminal without a fill.
func (e *Engine) exitOrderState(ctx context.Context, orderID string) (filled bool, price float64, done bool) {
	if e.exec == nil || strings.TrimSpace(orderID) == "" {
		return false, 0, true
	}
	foundID, status, price, err := e.exec.Lookup(ctx, orderID, "")
	if err != nil {
		if errors.Is(err, ErrExecutorUnavailable) || errors.Is(err, ErrOrderNotFound) {
			// The order cannot be found; treat it as terminal.
			return false, 0, true
		}
		// Unknown state: never place a second exit.
		return false, 0, false
	}
	if strings.TrimSpace(foundID) == "" {
		return false, 0, true
	}
	if isFilledStatus(status) {
		return true, price, true
	}
	if isCancelledStatus(status) {
		return false, 0, true
	}
	return false, 0, false
}

// exitOrderByTag finds an existing exit order for a bracket by its deterministic
// client tag. It covers a placement whose response was lost. A lookup failure
// other than "not found" is returned as an error so callers never place a
// second exit on unknown state.
func (e *Engine) exitOrderByTag(ctx context.Context, bracketID string) (orderID, status string, price float64, found bool, err error) {
	if e.exec == nil {
		return "", "", 0, false, nil
	}
	foundID, status, price, err := e.exec.Lookup(ctx, "", "exit_"+bracketID)
	if err != nil {
		if errors.Is(err, ErrExecutorUnavailable) || errors.Is(err, ErrOrderNotFound) {
			return "", "", 0, false, nil
		}
		return "", "", 0, false, err
	}
	if strings.TrimSpace(foundID) == "" {
		return "", "", 0, false, nil
	}
	return foundID, status, price, true, nil
}

// adoptExitFill records an exit that an existing order already completed.
func (e *Engine) adoptExitFill(ctx context.Context, id string, price float64) {
	e.mu.Lock()
	b, ok := e.brackets[id]
	if !ok {
		e.mu.Unlock()
		return
	}
	if b.Status == StatusCancelled {
		e.mu.Unlock()
		return
	}
	exchangeStopOrderID := b.ExchangeStopOrderID
	wasWorking := b.ExchangeStopIsWorking()
	e.unindexActiveInPosition(b)
	b.Status = StatusExitedManual
	if price > 0 {
		b.ExitPrice = price
		if b.TransactionType == "BUY" {
			b.PnL = (b.ExitPrice - b.EntryPrice) * float64(b.Quantity)
		} else {
			b.PnL = (b.EntryPrice - b.ExitPrice) * float64(b.Quantity)
		}
	}
	b.UpdatedAt = time.Now()
	cp := *b
	e.mu.Unlock()

	if wasWorking && exchangeStopOrderID != "" {
		if filled, p, err := e.cancelExchangeStopOrder(ctx, exchangeStopOrderID); filled {
			e.markExchangeStopFill(ctx, id, p)
			return
		} else if err != nil {
			e.log.Error("CRITICAL: failed to cancel exchange backstop after external exit",
				"id", id, "order_id", exchangeStopOrderID, "error", err)
		} else {
			e.setExchangeStopStatus(ctx, id, ExchangeStopCancelled)
		}
	}
	e.persistBracket(ctx, cp)
	e.notify(cp)
}

// Disarm marks an active or pending bracket as externally squared off/cancelled
// without placing duplicate market exit orders.
func (e *Engine) Disarm(ctx context.Context, id string) error {
	e.mu.Lock()
	b, ok := e.brackets[id]
	if !ok {
		e.mu.Unlock()
		return errors.New("bracket not found")
	}
	if b.Status == StatusPendingEntry {
		// A pending bracket still has a working entry order. Cancel it before
		// marking the bracket done, otherwise the order can fill unmanaged.
		entryOrderID := b.EntryOrderID
		e.mu.Unlock()

		filled, price, err := e.cancelEntryOrder(ctx, entryOrderID)
		if err != nil {
			return fmt.Errorf("bracket: cancel entry order %s: %w", entryOrderID, err)
		}

		e.mu.Lock()
		b, ok = e.brackets[id]
		if !ok {
			e.mu.Unlock()
			return nil
		}
		if filled {
			b.Status = StatusInPosition
			if price > 0 {
				b.EntryPrice = price
			}
			b.UpdatedAt = time.Now()
			e.indexActiveInPosition(b)
			cp := *b
			e.mu.Unlock()
			e.persistBracket(ctx, cp)
			e.notify(cp)
			e.ensureExchangeStop(ctx, id)
			return fmt.Errorf("bracket: entry order %s filled before disarm", entryOrderID)
		}
		if b.Status != StatusPendingEntry {
			status := b.Status
			e.mu.Unlock()
			if status == StatusCancelled {
				return nil
			}
			return fmt.Errorf("bracket %s cannot be disarmed in status %s", id, status)
		}
		e.unindexActiveInPosition(b)
		b.Status = StatusCancelled
		b.UpdatedAt = time.Now()
		cp := *b
		e.mu.Unlock()
		e.persistBracket(ctx, cp)
		e.notify(cp)
		return nil
	}

	exchangeStopOrderID := b.ExchangeStopOrderID
	e.unindexActiveInPosition(b)
	b.Status = StatusExitedManual
	b.UpdatedAt = time.Now()
	bracketCopy := *b
	e.mu.Unlock()

	if exchangeStopOrderID != "" {
		if filled, price, err := e.cancelExchangeStopOrder(ctx, exchangeStopOrderID); filled {
			e.markExchangeStopFill(ctx, id, price)
			return nil
		} else if err != nil {
			e.log.Error("CRITICAL: failed to cancel exchange stop while disarming bracket", "id", id, "order_id", exchangeStopOrderID, "error", err)
		} else {
			e.setExchangeStopStatus(ctx, id, ExchangeStopCancelled)
		}
	}

	e.persistBracket(ctx, bracketCopy)
	e.notify(bracketCopy)
	return nil
}

// UpdateQuantity resizes an in-position bracket after a partial manual exit so
// its SL/TP does not overshoot the remaining position. A working exchange
// backstop is replaced for the new quantity.
func (e *Engine) UpdateQuantity(ctx context.Context, id string, qty int64) error {
	if qty <= 0 {
		return errors.New("bracket: quantity must be positive")
	}
	e.mu.Lock()
	b, ok := e.brackets[id]
	if !ok {
		e.mu.Unlock()
		return errors.New("bracket not found")
	}
	if b.Status != StatusInPosition && b.Status != StatusExitFailed {
		status := b.Status
		e.mu.Unlock()
		return fmt.Errorf("bracket %s cannot be resized in status %s", id, status)
	}
	if b.Quantity == qty {
		e.mu.Unlock()
		return nil
	}
	oldQty := b.Quantity
	b.Quantity = qty
	b.UpdatedAt = time.Now()
	hadBackstop := b.ExchangeStopOrderID != "" || b.ExchangeStopIsWorking()
	cp := *b
	e.mu.Unlock()

	e.persistBracket(ctx, cp)
	e.notify(cp)
	if hadBackstop {
		if err := e.cancelExchangeStopForBracket(ctx, id); err != nil {
			// The old stop may still be live; keep the original size so the
			// bracket and the broker order agree.
			e.mu.Lock()
			var restored Bracket
			restoredOK := false
			if curr, ok := e.brackets[id]; ok {
				curr.Quantity = oldQty
				curr.UpdatedAt = time.Now()
				restored = *curr
				restoredOK = true
			}
			e.mu.Unlock()
			if restoredOK {
				e.persistBracket(ctx, restored)
				e.notify(restored)
			}
			return fmt.Errorf("bracket: resize blocked by backstop cancel: %w", err)
		}
		e.ensureExchangeStop(ctx, id)
	}
	return nil
}

// Rearm restores an in-position bracket that was disarmed while its position
// stayed open, for example when a square-off close order failed.
func (e *Engine) Rearm(ctx context.Context, id string) error {
	e.mu.Lock()
	b, ok := e.brackets[id]
	if !ok {
		e.mu.Unlock()
		return errors.New("bracket not found")
	}
	if b.Status != StatusExitedManual {
		status := b.Status
		e.mu.Unlock()
		return fmt.Errorf("bracket %s cannot be re-armed in status %s", id, status)
	}
	exitOrderID := b.ExitOrderID
	e.mu.Unlock()

	if exitOrderID != "" {
		filled, price, done := e.exitOrderState(ctx, exitOrderID)
		if filled {
			e.adoptExitFill(ctx, id, price)
			return nil
		}
		if !done {
			return fmt.Errorf("bracket %s exit order %s is still working", id, exitOrderID)
		}
	}

	e.mu.Lock()
	b, ok = e.brackets[id]
	if !ok {
		e.mu.Unlock()
		return nil
	}
	if b.Status != StatusExitedManual {
		status := b.Status
		e.mu.Unlock()
		return fmt.Errorf("bracket %s cannot be re-armed in status %s", id, status)
	}
	b.Status = StatusInPosition
	b.ExitPrice = 0
	b.ExitOrderID = ""
	b.PnL = 0
	b.UpdatedAt = time.Now()
	e.indexActiveInPosition(b)
	cp := *b
	e.mu.Unlock()

	e.persistBracket(ctx, cp)
	e.notify(cp)
	e.ensureExchangeStop(ctx, id)
	return nil
}

// MarkExternalExit records an exit that was executed outside the engine, such
// as a paper square-off. It cancels a working entry order or exchange backstop
// first and never places a market exit.
func (e *Engine) MarkExternalExit(ctx context.Context, id string, price float64) error {
	e.mu.Lock()
	b, ok := e.brackets[id]
	if !ok {
		e.mu.Unlock()
		return errors.New("bracket not found")
	}
	if b.Status == StatusCancelled {
		e.mu.Unlock()
		return nil
	}
	wasPending := b.Status == StatusPendingEntry
	entryOrderID := b.EntryOrderID
	exchangeStopOrderID := b.ExchangeStopOrderID
	wasWorking := b.ExchangeStopIsWorking()
	e.mu.Unlock()

	if wasPending && entryOrderID != "" {
		filled, fillPrice, err := e.cancelEntryOrder(ctx, entryOrderID)
		if err != nil {
			return fmt.Errorf("bracket: cancel entry order %s: %w", entryOrderID, err)
		}
		if filled {
			e.mu.Lock()
			curr, ok := e.brackets[id]
			if !ok {
				e.mu.Unlock()
				return fmt.Errorf("bracket: entry order %s filled before external exit", entryOrderID)
			}
			curr.Status = StatusInPosition
			if fillPrice > 0 {
				curr.EntryPrice = fillPrice
			}
			curr.UpdatedAt = time.Now()
			e.indexActiveInPosition(curr)
			cp := *curr
			e.mu.Unlock()
			e.persistBracket(ctx, cp)
			e.notify(cp)
			e.ensureExchangeStop(ctx, id)
			return fmt.Errorf("bracket: entry order %s filled before external exit", entryOrderID)
		}
	}

	if wasWorking && exchangeStopOrderID != "" {
		if filled, fillPrice, err := e.cancelExchangeStopOrder(ctx, exchangeStopOrderID); filled {
			e.markExchangeStopFill(ctx, id, fillPrice)
			return nil
		} else if err != nil {
			return fmt.Errorf("bracket: cancel exchange stop before external exit: %w", err)
		}
	}

	e.mu.Lock()
	b, ok = e.brackets[id]
	if !ok {
		e.mu.Unlock()
		return nil
	}
	if b.Status == StatusCancelled {
		e.mu.Unlock()
		return nil
	}
	e.unindexActiveInPosition(b)
	if wasPending {
		b.Status = StatusCancelled
	} else {
		b.Status = StatusExitedManual
		if price > 0 {
			b.ExitPrice = price
			if b.TransactionType == "BUY" {
				b.PnL = (b.ExitPrice - b.EntryPrice) * float64(b.Quantity)
			} else {
				b.PnL = (b.EntryPrice - b.ExitPrice) * float64(b.Quantity)
			}
		}
	}
	if wasWorking {
		b.ExchangeStopStatus = ExchangeStopCancelled
	}
	b.UpdatedAt = time.Now()
	updated := *b
	e.mu.Unlock()

	e.persistBracket(ctx, updated)
	e.notify(updated)
	return nil
}

// OnOrderModified keeps a pending bracket's entry price in sync when its
// resting order is changed through the order API rather than the engine.
func (e *Engine) OnOrderModified(ctx context.Context, orderID string, price float64, qty int64) {
	orderID = strings.TrimSpace(orderID)
	if orderID == "" || price <= 0 {
		return
	}
	e.mu.Lock()
	var updated *Bracket
	for _, b := range e.brackets {
		if b.EntryOrderID != orderID || b.Status != StatusPendingEntry {
			continue
		}
		if err := validateLevels(b.TransactionType, price, b.TargetPrice, b.StopLossPrice); err != nil {
			e.log.Warn("rejected invalid bracket entry modification", "id", b.ID, "price", price, "error", err)
			break
		}
		b.EntryPrice = price
		if qty > 0 {
			b.Quantity = qty
		}
		b.UpdatedAt = time.Now()
		cp := *b
		updated = &cp
		break
	}
	e.mu.Unlock()
	if updated == nil {
		return
	}
	if e.store != nil {
		pctx, cancel := context.WithTimeout(context.WithoutCancel(ctx), 5*time.Second)
		defer cancel()
		if err := e.store.UpdateBracket(pctx, *updated); err != nil {
			e.log.Error("failed to persist modified bracket entry", "id", updated.ID, "error", err)
		}
	}
	e.notify(*updated)
}

// Exit squares off a bracket manually by cancelling resting orders and placing a market exit order.
func (e *Engine) Exit(ctx context.Context, id string) error {
	e.mu.Lock()
	b, ok := e.brackets[id]
	if !ok {
		e.mu.Unlock()
		return errors.New("bracket not found")
	}
	if b.Status != StatusPendingEntry && b.Status != StatusInPosition && b.Status != StatusExitFailed {
		currStatus := b.Status
		e.mu.Unlock()
		return fmt.Errorf("bracket %s cannot be exited in status %s", id, currStatus)
	}

	if b.Status == StatusPendingEntry {
		// Entry not filled; cancel the resting entry order before marking the
		// bracket done. If the cancel cannot be confirmed, keep it pending so a
		// later fill is still managed.
		orderToCancel := b.EntryOrderID
		e.mu.Unlock()

		filled, price, err := e.cancelEntryOrder(ctx, orderToCancel)
		if err != nil {
			return fmt.Errorf("bracket: cancel entry order %s: %w", orderToCancel, err)
		}

		e.mu.Lock()
		curr, ok := e.brackets[id]
		if !ok {
			e.mu.Unlock()
			return nil
		}
		if filled {
			curr.Status = StatusInPosition
			if price > 0 {
				curr.EntryPrice = price
			}
			curr.UpdatedAt = time.Now()
			e.indexActiveInPosition(curr)
			cp := *curr
			e.mu.Unlock()
			e.persistBracket(ctx, cp)
			e.notify(cp)
			e.ensureExchangeStop(ctx, id)
			return fmt.Errorf("bracket: entry order %s filled before exit; retry", orderToCancel)
		}
		if curr.Status != StatusPendingEntry {
			status := curr.Status
			e.mu.Unlock()
			if status == StatusCancelled {
				return nil
			}
			return fmt.Errorf("bracket %s cannot be exited in status %s", id, status)
		}
		e.unindexActiveInPosition(curr)
		curr.Status = StatusCancelled
		curr.UpdatedAt = time.Now()
		bracketCopy := *curr
		e.mu.Unlock()

		e.persistBracket(ctx, bracketCopy)
		e.notify(bracketCopy)
		return nil
	}

	// In position or failed exit. Check for an existing exit order *before*
	// mutating state or cancelling the backstop, so an unknown lookup cannot
	// leave the position unprotected.
	restingOrder := b.ExitOrderID
	exchangeStopOrderID := ""
	if b.ExchangeStopIsWorking() || b.ExchangeStopOrderID != "" {
		exchangeStopOrderID = b.ExchangeStopOrderID
	}
	exitSide := "SELL"
	if strings.ToUpper(b.TransactionType) == "SELL" {
		exitSide = "BUY"
	}
	exitOrder := kotakapi.Order{
		Tag:             "exit_" + b.ID,
		InstrumentKey:   b.InstrumentKey,
		ExchangeSegment: b.ExchangeSegment,
		TradingSymbol:   b.TradingSymbol,
		TransactionType: exitSide,
		Product:         b.Product,
		OrderType:       "MKT",
		Quantity:        b.Quantity,
		Validity:        "DAY",
	}
	e.mu.Unlock()

	ctx = kotakhttp.WithPriority(ctx)

	if orderID, status, price, found, lookupErr := e.exitOrderByTag(ctx, id); lookupErr != nil {
		return fmt.Errorf("bracket: check existing exit order: %w", lookupErr)
	} else if found {
		if isFilledStatus(status) {
			e.adoptExitFill(ctx, id, price)
			return nil
		}
		if !isCancelledStatus(status) {
			return fmt.Errorf("bracket %s already has a working exit order %s", id, orderID)
		}
	}

	if restingOrder != "" && e.exec != nil {
		filled, price, done := e.exitOrderState(ctx, restingOrder)
		if filled {
			e.adoptExitFill(ctx, id, price)
			return nil
		}
		if !done {
			return fmt.Errorf("bracket %s exit order %s is still working", id, restingOrder)
		}
		_ = e.exec.Cancel(ctx, restingOrder)
	}

	e.mu.Lock()
	curr, ok := e.brackets[id]
	if !ok {
		e.mu.Unlock()
		return nil
	}
	if curr.Status != StatusInPosition && curr.Status != StatusExitFailed {
		status := curr.Status
		e.mu.Unlock()
		return fmt.Errorf("bracket %s cannot be exited in status %s", id, status)
	}
	e.unindexActiveInPosition(curr)
	curr.Status = StatusExitedManual
	curr.UpdatedAt = time.Now()
	bracketCopy := *curr
	e.mu.Unlock()

	if exchangeStopOrderID != "" {
		filled, price, cancelErr := e.cancelExchangeStopOrder(ctx, exchangeStopOrderID)
		if filled {
			e.markExchangeStopFill(ctx, id, price)
			return nil
		}
		if cancelErr != nil {
			e.log.Error("CRITICAL: failed to cancel exchange backstop before manual exit",
				"id", id, "order_id", exchangeStopOrderID, "error", cancelErr)
			e.mu.Lock()
			if curr, ok := e.brackets[id]; ok {
				curr.Status = StatusExitFailed
				curr.UpdatedAt = time.Now()
				e.indexActiveInPosition(curr)
				bracketCopy = *curr
			}
			e.mu.Unlock()
			e.persistBracket(ctx, bracketCopy)
			e.notify(bracketCopy)
			return fmt.Errorf("could not cancel exchange backstop before exit: %w", cancelErr)
		}
		e.setExchangeStopStatus(ctx, id, ExchangeStopCancelled)
	}

	var exitErr error
	var orderID string
	if e.exec != nil {
	exitRetryLoop:
		for attempt := 0; attempt < 3; attempt++ {
			if attempt > 0 {
				select {
				case <-ctx.Done():
					exitErr = ctx.Err()
					break exitRetryLoop
				case <-time.After(50 * time.Millisecond):
				}
			}
			orderID, exitErr = e.exec.Place(ctx, exitOrder)
			if exitErr == nil && orderID != "" {
				break exitRetryLoop
			}
		}
		if exitErr == nil && orderID == "" {
			exitErr = errors.New("executor returned an empty order id")
		}
	}

	e.mu.Lock()
	if curr, ok := e.brackets[id]; ok {
		if exitErr != nil {
			e.log.Error("CRITICAL: failed to place exit order on manual exit", "id", id, "error", exitErr)
			curr.Status = StatusExitFailed
			curr.UpdatedAt = time.Now()
			e.indexActiveInPosition(curr) // re-index so user or engine can retry exit
			bracketCopy = *curr
		} else {
			curr.ExitOrderID = orderID
			if unmatched, found := e.unmatchedOrders[orderID]; found {
				delete(e.unmatchedOrders, orderID)
				if isFilledStatus(unmatched.Status) {
					curr.Status = StatusExitedManual
					if unmatched.FilledPrice > 0 {
						curr.ExitPrice = unmatched.FilledPrice
					}
				}
			}
			bracketCopy = *curr
		}
	}
	e.mu.Unlock()

	e.persistBracket(ctx, bracketCopy)
	e.notify(bracketCopy)
	if exitErr != nil {
		return fmt.Errorf("failed to execute market exit order: %w", exitErr)
	}
	return nil
}

// List returns stored and active brackets up to limit, ordered newest first.
func (e *Engine) List(limit int) ([]Bracket, error) {
	e.mu.RLock()
	defer e.mu.RUnlock()

	result := make([]Bracket, 0, len(e.brackets))
	for _, b := range e.brackets {
		cp := *b
		if (cp.Underlying == "" || cp.Strike == 0 || cp.OptionType == "") && strings.Contains(cp.InstrumentKey, "|") {
			parts := strings.Split(cp.InstrumentKey, "|")
			if len(parts) >= 5 {
				if cp.Underlying == "" {
					cp.Underlying = parts[1]
				}
				if cp.Strike == 0 {
					if s, err := strconv.ParseFloat(parts[3], 64); err == nil {
						cp.Strike = s
					}
				}
				if cp.OptionType == "" {
					cp.OptionType = strings.ToUpper(parts[4])
				}
			}
		}
		result = append(result, cp)
	}

	sort.Slice(result, func(i, j int) bool {
		return result[i].CreatedAt.After(result[j].CreatedAt)
	})

	if limit > 0 && len(result) > limit {
		result = result[:limit]
	}
	return result, nil
}

// Get looks up a bracket by ID from in-memory cache.
func (e *Engine) Get(id string) (*Bracket, bool) {
	e.mu.RLock()
	defer e.mu.RUnlock()

	b, ok := e.brackets[id]
	if !ok {
		return nil, false
	}
	bracketCopy := *b
	return &bracketCopy, true
}

// OnOrderEvent processes an order feed event and updates bracket position state when entry/exit orders fill.
func (e *Engine) OnOrderEvent(ctx context.Context, event orderfeed.Event) {
	if len(event.Data) == 0 {
		return
	}

	orders := parseOrderData(event.Data)
	for _, ord := range orders {
		e.handleOrderUpdate(ctx, ord)
	}
}

// OnFill applies a normalized fill delivered by an Executor. Live order-feed
// events and paper-simulated fills both converge here.
func (e *Engine) OnFill(ctx context.Context, fill Fill) {
	if strings.TrimSpace(fill.OrderID) == "" && strings.TrimSpace(fill.Tag) == "" {
		return
	}
	e.handleOrderUpdate(ctx, parsedOrder{
		OrderID:     fill.OrderID,
		Tag:         fill.Tag,
		Status:      fill.Status,
		FilledPrice: fill.Price,
	})
}

type parsedOrder struct {
	OrderID     string
	Tag         string
	Status      string
	FilledPrice float64
}

func parseOrderData(data json.RawMessage) []parsedOrder {
	trimmed := strings.TrimSpace(string(data))
	if strings.HasPrefix(trimmed, "[") {
		var list []map[string]any
		if err := json.Unmarshal(data, &list); err == nil {
			var res []parsedOrder
			for _, item := range list {
				if po, ok := extractParsedOrder(item); ok {
					res = append(res, po)
				}
			}
			return res
		}
	}

	var single map[string]any
	if err := json.Unmarshal(data, &single); err == nil {
		if po, ok := extractParsedOrder(single); ok {
			return []parsedOrder{po}
		}
	}
	return nil
}

func extractParsedOrder(m map[string]any) (parsedOrder, bool) {
	var po parsedOrder

	// Check order ID fields
	for _, k := range []string{"order_id", "nOrdNo", "nordno", "ordId", "ordid", "broker_order_id", "client_order_id", "id"} {
		if v, ok := m[k]; ok && v != nil {
			str := fmt.Sprint(v)
			if str != "" && str != "—" && str != "<nil>" {
				po.OrderID = str
				break
			}
		}
	}
	// Check tag / correlation ID fields
	for _, k := range []string{"tag", "client_order_id", "guiOrdId", "gui_order_id", "tag_id"} {
		if v, ok := m[k]; ok && v != nil {
			str := strings.TrimSpace(fmt.Sprint(v))
			if str != "" && str != "—" && str != "<nil>" {
				po.Tag = str
				break
			}
		}
	}
	if po.OrderID == "" && po.Tag == "" {
		return po, false
	}

	// Check status fields
	for _, k := range []string{"status", "ordSt", "ordst", "order_status"} {
		if v, ok := m[k]; ok && v != nil {
			po.Status = strings.ToUpper(strings.TrimSpace(fmt.Sprint(v)))
			break
		}
	}

	// Check filled price fields
	for _, k := range []string{"avgPrc", "avgprc", "avg_price", "average_price", "price", "prc"} {
		if v, ok := m[k]; ok && v != nil {
			switch val := v.(type) {
			case float64:
				po.FilledPrice = val
			case int64:
				po.FilledPrice = float64(val)
			case int:
				po.FilledPrice = float64(val)
			case string:
				if p, err := strconv.ParseFloat(val, 64); err == nil {
					po.FilledPrice = p
				}
			}
			if po.FilledPrice > 0 {
				break
			}
		}
	}

	return po, true
}

func isFilledStatus(status string) bool {
	switch strings.ToUpper(status) {
	case "TRAD", "COMPLETE", "EXECUTED", "FILLED":
		return true
	default:
		return false
	}
}

func isCancelledStatus(status string) bool {
	switch strings.ToUpper(status) {
	case "CAN", "CANCELLED", "REJ", "REJECTED", "EXPIRED":
		return true
	default:
		return false
	}
}

// IsFilledStatus reports whether a broker order status means the order
// executed. It is exported for callers that reconcile manual orders.
func IsFilledStatus(status string) bool { return isFilledStatus(status) }

// IsCancelledStatus reports whether a broker order status is terminal without
// a fill. It is exported for callers that reconcile manual orders.
func IsCancelledStatus(status string) bool { return isCancelledStatus(status) }

func (e *Engine) handleOrderUpdate(ctx context.Context, ord parsedOrder) {
	e.mu.Lock()
	var updated *Bracket
	entryFilledID := ""
	matched := false
	for _, b := range e.brackets {
		isEntryMatch := (b.EntryOrderID == ord.OrderID && ord.OrderID != "") || (ord.Tag != "" && ord.Tag == b.ID)
		if isEntryMatch && (b.Status == StatusPendingEntry || b.Status == "") {
			matched = true
			if isFilledStatus(ord.Status) {
				b.Status = StatusInPosition
				if ord.FilledPrice > 0 {
					b.EntryPrice = ord.FilledPrice
				}
				b.UpdatedAt = time.Now()
				e.indexActiveInPosition(b)
				entryFilledID = b.ID
				cp := *b
				updated = &cp
				break
			} else if isCancelledStatus(ord.Status) {
				b.Status = StatusCancelled
				b.UpdatedAt = time.Now()
				cp := *b
				updated = &cp
				break
			}
		}

		isExchangeStopMatch := (b.ExchangeStopOrderID != "" && b.ExchangeStopOrderID == ord.OrderID) ||
			(ord.Tag != "" && ord.Tag == exchangeStopTag(b.ID))
		if isExchangeStopMatch {
			matched = true
			if isFilledStatus(ord.Status) {
				e.applyExchangeStopFillLocked(b, ord.FilledPrice)
				cp := *b
				updated = &cp
				break
			}
			if terminal := exchangeStopTerminalStatus(ord.Status); terminal != "" {
				e.log.Error("CRITICAL: exchange backstop was rejected or cancelled by broker",
					"bracket_id", b.ID, "order_id", ord.OrderID, "status", ord.Status)
				b.ExchangeStopStatus = terminal
				b.UpdatedAt = time.Now()
				cp := *b
				updated = &cp
				break
			}
		}

		isExitMatch := (b.ExitOrderID == ord.OrderID && ord.OrderID != "") || (ord.Tag != "" && ord.Tag == "exit_"+b.ID)
		if isExitMatch {
			matched = true
			if isFilledStatus(ord.Status) {
				e.unindexActiveInPosition(b)
				if b.Status == StatusInPosition || b.Status == StatusExitFailed {
					b.Status = StatusExitedManual
				}
				if ord.FilledPrice > 0 {
					b.ExitPrice = ord.FilledPrice
					if b.TransactionType == "BUY" {
						b.PnL = (b.ExitPrice - b.EntryPrice) * float64(b.Quantity)
					} else {
						b.PnL = (b.EntryPrice - b.ExitPrice) * float64(b.Quantity)
					}
				}
				b.UpdatedAt = time.Now()
				cp := *b
				updated = &cp
				break
			} else if isCancelledStatus(ord.Status) {
				e.log.Error("CRITICAL: exit order was rejected or cancelled by broker",
					"bracket_id", b.ID, "order_id", ord.OrderID, "status", ord.Status)
				b.Status = StatusExitFailed
				b.UpdatedAt = time.Now()
				e.indexActiveInPosition(b) // re-index to enable manual exit or retry
				cp := *b
				updated = &cp
				break
			}
		}
	}
	if !matched && ord.OrderID != "" {
		if e.unmatchedOrders == nil {
			e.unmatchedOrders = make(map[string]parsedOrder)
		}
		e.unmatchedOrders[ord.OrderID] = ord
		if len(e.unmatchedOrders) > 200 {
			for k := range e.unmatchedOrders {
				delete(e.unmatchedOrders, k)
				break
			}
		}
	}
	e.mu.Unlock()

	if updated != nil {
		if e.store != nil {
			if err := e.store.UpdateBracket(ctx, *updated); err != nil {
				e.log.Error("failed to update bracket on order event", "id", updated.ID, "error", err)
			}
		}
		e.notify(*updated)
	}
	if entryFilledID != "" {
		e.ensureExchangeStop(ctx, entryFilledID)
	}
}

type tickTrigger struct {
	bracketID         string
	exitSide          string
	exitQuantity      int64
	instrumentKey     string
	segment           string
	symbol            string
	product           string
	restingOrder      string
	exchangeStopOrder string
	newStatus         string
	exitPrice         float64
	pnl               float64
}

// OnTick evaluates current market price against active IN_POSITION brackets, triggering target or stoploss exits.
func (e *Engine) OnTick(ctx context.Context, instrumentKey string, ltp float64) {
	if instrumentKey == "" || ltp <= 0 {
		return
	}
	if e.activeInPos.Load() == 0 {
		return
	}
	if _, active := e.activeKeys.Load(instrumentKey); !active {
		return
	}

	var triggers []tickTrigger

	e.mu.Lock()
	activeMap := e.activeByInstrument[instrumentKey]
	if len(activeMap) == 0 {
		e.mu.Unlock()
		return
	}

	for _, b := range activeMap {
		if b.Status != StatusInPosition && b.Status != StatusExitFailed {
			continue
		}
		if b.Status == StatusExitFailed && time.Since(b.UpdatedAt) < 3*time.Second {
			continue
		}

		isLong := b.TransactionType == "BUY"

		// Dynamic trailing stop adjustment
		if b.TrailingStop > 0 {
			trailed := false
			if isLong {
				trailSL := ltp - b.TrailingStop
				if trailSL > b.StopLossPrice {
					b.StopLossPrice = trailSL
					b.UpdatedAt = time.Now()
					trailed = true
				}
			} else {
				trailSL := ltp + b.TrailingStop
				if b.StopLossPrice == 0 || trailSL < b.StopLossPrice {
					b.StopLossPrice = trailSL
					b.UpdatedAt = time.Now()
					trailed = true
				}
			}
			if trailed && e.store != nil {
				// Coalesce trailing-stop persistence: the in-memory stop is
				// updated every tick, but SQLite writes are capped at 2s per
				// bracket to avoid a goroutine + write per tick.
				if time.Since(e.lastTrailPersist[b.ID]) >= 2*time.Second {
					e.lastTrailPersist[b.ID] = time.Now()
					cp := *b
					go func(br Bracket) {
						ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
						defer cancel()
						_ = e.store.UpdateBracket(ctx, br)
					}(cp)
				}
			}
		}

		hitStatus := ""
		if isLong {
			if b.TargetPrice > 0 && ltp >= b.TargetPrice {
				hitStatus = StatusTargetHit
			} else if b.StopLossPrice > 0 && ltp <= b.StopLossPrice {
				hitStatus = StatusSLHit
			}
		} else {
			if b.TargetPrice > 0 && ltp <= b.TargetPrice {
				hitStatus = StatusTargetHit
			} else if b.StopLossPrice > 0 && ltp >= b.StopLossPrice {
				hitStatus = StatusSLHit
			}
		}

		if hitStatus == "" {
			continue
		}

		// Mutate status under lock immediately so duplicate ticks will not re-trigger exit
		b.Status = hitStatus
		b.ExitPrice = ltp
		if isLong {
			b.PnL = (b.ExitPrice - b.EntryPrice) * float64(b.Quantity)
		} else {
			b.PnL = (b.EntryPrice - b.ExitPrice) * float64(b.Quantity)
		}
		b.UpdatedAt = time.Now()

		exitSide := "SELL"
		if !isLong {
			exitSide = "BUY"
		}

		triggers = append(triggers, tickTrigger{
			bracketID:         b.ID,
			exitSide:          exitSide,
			exitQuantity:      b.Quantity,
			instrumentKey:     b.InstrumentKey,
			segment:           b.ExchangeSegment,
			symbol:            b.TradingSymbol,
			product:           b.Product,
			restingOrder:      b.ExitOrderID,
			exchangeStopOrder: b.ExchangeStopOrderID,
			newStatus:         hitStatus,
			exitPrice:         b.ExitPrice,
			pnl:               b.PnL,
		})
	}
	for _, trg := range triggers {
		if b, ok := e.brackets[trg.bracketID]; ok {
			e.unindexActiveInPosition(b)
		}
	}
	isAsync := e.asyncExecution
	e.mu.Unlock()

	for _, trg := range triggers {
		if isAsync {
			trgCopy := trg
			go e.processTriggerExit(ctx, trgCopy)
		} else {
			e.processTriggerExit(ctx, trg)
		}
	}
}

func (e *Engine) processTriggerExit(ctx context.Context, trg tickTrigger) {
	if ctx == nil {
		ctx = context.Background()
	}
	ctx = kotakhttp.WithPriority(ctx)

	// Check for an existing exit order before touching the backstop, so an
	// unknown lookup cannot leave the position naked.
	if orderID, status, price, found, lookupErr := e.exitOrderByTag(ctx, trg.bracketID); lookupErr != nil {
		e.log.Error("CRITICAL: could not check existing exit order; not placing a second exit",
			"bracket_id", trg.bracketID, "error", lookupErr)
		e.failTriggerExit(ctx, trg.bracketID)
		return
	} else if found {
		if isFilledStatus(status) {
			e.adoptExitFill(ctx, trg.bracketID, price)
			return
		}
		if !isCancelledStatus(status) {
			e.log.Warn("existing exit order is still working; parking for retry",
				"bracket_id", trg.bracketID, "order_id", orderID)
			e.failTriggerExit(ctx, trg.bracketID)
			return
		}
	}

	if trg.restingOrder != "" && e.exec != nil {
		filled, price, done := e.exitOrderState(ctx, trg.restingOrder)
		if filled {
			e.adoptExitFill(ctx, trg.bracketID, price)
			return
		}
		if !done {
			e.log.Warn("existing exit order is still working; parking for retry",
				"bracket_id", trg.bracketID, "order_id", trg.restingOrder)
			e.failTriggerExit(ctx, trg.bracketID)
			return
		}
		if err := e.exec.Cancel(ctx, trg.restingOrder); err != nil {
			e.log.Warn("failed to cancel resting order on bracket trigger", "bracket_id", trg.bracketID, "order_id", trg.restingOrder, "error", err)
		}
	}

	if trg.exchangeStopOrder != "" {
		filled, price, cancelErr := e.cancelExchangeStopOrder(ctx, trg.exchangeStopOrder)
		if filled {
			e.markExchangeStopFill(ctx, trg.bracketID, price)
			return
		}
		if cancelErr != nil {
			if strings.EqualFold(e.exchangeStopConfig().OnCancelFailure, "place_exit_anyway") {
				e.log.Warn("placing normal exit despite unconfirmed exchange stop cancellation",
					"bracket_id", trg.bracketID, "order_id", trg.exchangeStopOrder, "error", cancelErr)
			} else {
				e.log.Error("CRITICAL: could not cancel exchange backstop; not placing a second sell",
					"bracket_id", trg.bracketID, "order_id", trg.exchangeStopOrder, "error", cancelErr)
				e.failTriggerExit(ctx, trg.bracketID)
				return
			}
		} else {
			e.setExchangeStopStatus(ctx, trg.bracketID, ExchangeStopCancelled)
		}
	}

	var placedOrderID string
	var placeErr error
	if e.exec != nil {
		exitOrder := kotakapi.Order{
			Tag:             "exit_" + trg.bracketID,
			InstrumentKey:   trg.instrumentKey,
			ExchangeSegment: trg.segment,
			TradingSymbol:   trg.symbol,
			TransactionType: trg.exitSide,
			Product:         trg.product,
			OrderType:       "MKT",
			Quantity:        trg.exitQuantity,
			Validity:        "DAY",
		}
	triggerRetryLoop:
		for attempt := 0; attempt < 3; attempt++ {
			if attempt > 0 {
				select {
				case <-ctx.Done():
					placeErr = ctx.Err()
					break triggerRetryLoop
				case <-time.After(50 * time.Millisecond):
				}
			}
			placedOrderID, placeErr = e.exec.Place(ctx, exitOrder)
			if placeErr == nil && placedOrderID != "" {
				break triggerRetryLoop
			}
		}
		if placeErr == nil && placedOrderID == "" {
			placeErr = errors.New("executor returned an empty order id")
		}
	}

	e.mu.Lock()
	var notified Bracket
	if curr, ok := e.brackets[trg.bracketID]; ok {
		if placeErr != nil {
			e.log.Error("CRITICAL: market exit order failed; transitioning to EXIT_FAILED",
				"bracket_id", trg.bracketID, "error", placeErr)
			curr.Status = StatusExitFailed
			curr.UpdatedAt = time.Now()
			e.indexActiveInPosition(curr) // re-index to allow retry or manual square-off
		} else {
			curr.Status = trg.newStatus
			curr.ExitOrderID = placedOrderID
			curr.UpdatedAt = time.Now()
			if unmatched, found := e.unmatchedOrders[placedOrderID]; found {
				delete(e.unmatchedOrders, placedOrderID)
				if isFilledStatus(unmatched.Status) {
					if unmatched.FilledPrice > 0 {
						curr.ExitPrice = unmatched.FilledPrice
						if curr.TransactionType == "BUY" {
							curr.PnL = (curr.ExitPrice - curr.EntryPrice) * float64(curr.Quantity)
						} else {
							curr.PnL = (curr.EntryPrice - curr.ExitPrice) * float64(curr.Quantity)
						}
					}
				}
			}
		}
		notified = *curr
	}
	e.mu.Unlock()

	if e.store != nil {
		if err := e.store.UpdateBracket(ctx, notified); err != nil {
			e.log.Error("failed to persist bracket exit in store", "bracket_id", trg.bracketID, "error", err)
		}
	}

	e.notify(notified)
}

func generateID() string {
	b := make([]byte, 8)
	_, _ = rand.Read(b)
	return fmt.Sprintf("brk_%s", hex.EncodeToString(b))
}
